import { ActivityIndicator, StyleSheet, View } from 'react-native';
import { router } from 'expo-router';
import { SafeAreaView } from 'react-native-safe-area-context';

import ErrorView from '@/components/error-view';
import { PokemonGrid } from '@/components/pokemon-grid';
import { ThemedText } from '@/components/themed-text';
import { RubikFonts, Spacing } from '@/constants/theme';
import { usePokemonList } from '@/hooks/use-pokemon-list';
import { useTheme } from '@/hooks/use-theme';
import type { Pokemon } from '@/services/pokemon';

export default function HomeScreen() {
  const theme = useTheme();
  // The list page by page, 20 Pokémon at a time
  const {
    data,
    error,
    fetchNextPage,
    hasNextPage,
    isError,
    isFetching,
    isFetchingNextPage,
    isFetchNextPageError,
    isPending,
    refetch,
  } = usePokemonList();

  // The name goes along in the route, so the placeholder can show it without a request
  function openPokemon(pokemon: Pokemon) {
    router.push({
      pathname: '/pokemon/[id]',
      params: { id: String(pokemon.id), name: pokemon.name },
    });
  }

  // The full error screen only when nothing is loaded yet
  // If a later page fails, the list stays and the footer shows "Try again"
  // data.pages is a list of pages, flatMap turns it into one list of Pokémon
  return (
    <SafeAreaView style={[styles.container, { backgroundColor: theme.background }]}>
      <ThemedText style={[styles.title, { color: theme.midnight }]}>All Pokémon</ThemedText>
      {isPending ? (
        <View style={styles.state}>
          <ActivityIndicator color={theme.purple} size="large" />
        </View>
      ) : isError && !data ? (
        <View style={styles.state}>
          <ErrorView
            message={error instanceof Error ? error.message : 'Unable to load Pokémon.'}
            onRetry={() => {
              void refetch();
            }}
          />
        </View>
      ) : !data ? (
        <View style={styles.state}>
          <ActivityIndicator color={theme.purple} size="large" />
        </View>
      ) : (
        <PokemonGrid
          hasNextPage={Boolean(hasNextPage)}
          isFetching={isFetching}
          isFetchingNextPage={isFetchingNextPage}
          isFetchNextPageError={isFetchNextPageError}
          onLoadMore={() => {
            void fetchNextPage();
          }}
          onRetryLoadMore={() => {
            void fetchNextPage();
          }}
          onSelectPokemon={openPokemon}
          pokemon={data.pages.flatMap((page) => page.pokemon)}
        />
      )}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    paddingTop: Spacing.three,
  },
  title: {
    paddingHorizontal: Spacing.three,
    marginBottom: Spacing.three,
    fontFamily: RubikFonts.medium,
    fontSize: 24,
    lineHeight: 30,
  },
  state: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: Spacing.three,
  },
});

