import { useInfiniteQuery } from '@tanstack/react-query';

import { getPokemonPage } from '@/services/pokemon';

// Loads the list page by page, data.pages holds every page loaded so far
export function usePokemonList() {
  return useInfiniteQuery({
    // Not ['pokemon', ...], so it never clashes with the detail key ['pokemon', id]
    queryKey: ['pokemonList'],
    queryFn: ({ pageParam }) => getPokemonPage(pageParam),
    // The first page starts at offset 0
    initialPageParam: 0,
    // undefined tells TanStack Query there is no next page
    getNextPageParam: (lastPage) => lastPage.nextOffset ?? undefined,
  });
}

