const assert = require('node:assert/strict');
const fs = require('node:fs');
const ts = require('typescript');
const source = fs.readFileSync('src/hooks/use-pokemon-search.ts', 'utf8');
const javascript = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS } }).outputText;
const loaded = { exports: {} };
const fakeRequire = (id) => id === '@tanstack/react-query' ? { useQuery: () => ({}) } : { getPokemonNames: async () => [] };
new Function('require', 'module', 'exports', javascript)(fakeRequire, loaded, loaded.exports);
const { filterPokemon } = loaded.exports;
const pokemon = [
  { id: 4, name: 'Charmander', spriteUrl: '' },
  { id: 5, name: 'Charmeleon', spriteUrl: '' },
  { id: 6, name: 'Charizard', spriteUrl: '' },
  { id: 25, name: 'Pikachu', spriteUrl: '' },
  { id: 151, name: 'Mew', spriteUrl: '' },
];
assert.deepEqual(filterPokemon(pokemon, 'ch').map(({ name }) => name), ['Charmander', 'Charmeleon', 'Charizard', 'Pikachu']);
assert.deepEqual(filterPokemon(pokemon, 'CH').map(({ name }) => name), ['Charmander', 'Charmeleon', 'Charizard', 'Pikachu']);
assert.deepEqual(filterPokemon(pokemon, '25').map(({ name }) => name), ['Pikachu']);
assert.deepEqual(filterPokemon(pokemon, '025').map(({ name }) => name), ['Pikachu']);
assert.deepEqual(filterPokemon(pokemon, 'mew').map(({ id }) => id), [151]);
assert.deepEqual(filterPokemon(pokemon, 'not found'), []);
console.log('Search filter acceptance checks passed.');
